//! **The WebAuthn specification's own test vectors.**
//!
//! PROVENANCE: W3C spec vectors — copied from `index.bs` of
//! `github.com/w3c/webauthn` (section *Test Vectors*, `sctn-test-vectors`),
//! generated by that repository's `test-vectors/webauthn-test-vectors.py`.
//! They were written by somebody else from the specification, so agreeing with
//! them is evidence about the format and not only about this crate's author.
//! They are NOT a browser: no authenticator in a browser produced these bytes.
//!
//! All of them use RP ID `example.org` and origin `https://example.org`.
//!
//! **Several carry no UV flag**, so they are checked with
//! [`UserVerification::NotRequired`] to prove the rest of the ceremony, and
//! then with [`UserVerification::Required`] to prove the proxy's setting
//! refuses them.

#![allow(clippy::expect_used, clippy::panic, clippy::unwrap_used)]

use crate::{
    Algorithm, Credential, Refusal, RelyingParty, UserVerification, parse_authenticator_data,
    verify_assertion, verify_registration,
};

const RP: RelyingParty<'static> = RelyingParty {
    id: "example.org",
    origin: "https://example.org",
};

fn hex(text: &str) -> Vec<u8> {
    assert!(text.len().is_multiple_of(2), "odd hex");
    (0..text.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&text[i..i + 2], 16).expect("hex"))
        .collect()
}

