fn register(
    uv: UserVerification,
    challenge: &str,
    client_data: &str,
    object: &str,
) -> Result<Credential, Refusal> {
    verify_registration(RP, uv, &hex(challenge), &hex(client_data), &hex(object))
}

#[test]
fn w3c_none_es256_registers_and_its_assertion_verifies() {
    use none_es256::*;
    let credential = register(
        UserVerification::NotRequired,
        REG_CHALLENGE,
        REG_CLIENT_DATA,
        ATTESTATION_OBJECT,
    )
    .expect("the specification's registration verifies");
    assert_eq!(credential.algorithm, Algorithm::Es256);
    assert_eq!(credential.id, hex(CREDENTIAL_ID));
    assert_eq!(credential.sign_count, 0);

    let asserted = verify_assertion(
        RP,
        UserVerification::NotRequired,
        &hex(AUTH_CHALLENGE),
        &credential,
        &hex(CREDENTIAL_ID),
        &hex(AUTH_CLIENT_DATA),
        &hex(AUTH_DATA),
        &hex(SIGNATURE),
    )
    .expect("the specification's assertion verifies");
    assert_eq!(asserted.sign_count, 0);
}

/// Its flags (0x59 at registration, 0x19 at authentication) carry no UV, so
/// the proxy's setting refuses both.
#[test]
fn w3c_none_es256_is_refused_where_user_verification_is_required() {
    use none_es256::*;
    assert_eq!(
        register(UserVerification::Required, REG_CHALLENGE, REG_CLIENT_DATA, ATTESTATION_OBJECT),
        Err(Refusal::UserNotVerified)
    );
    let credential = register(
        UserVerification::NotRequired,
        REG_CHALLENGE,
        REG_CLIENT_DATA,
        ATTESTATION_OBJECT,
    )
    .expect("registers");
    assert_eq!(
        verify_assertion(
            RP,
            UserVerification::Required,
            &hex(AUTH_CHALLENGE),
            &credential,
            &hex(CREDENTIAL_ID),
            &hex(AUTH_CLIENT_DATA),
            &hex(AUTH_DATA),
            &hex(SIGNATURE),
        ),
        Err(Refusal::UserNotVerified)
    );
}

/// The specification's bytes, with one bit of the signature changed, and with
/// the other ceremony's challenge: both refused.
#[test]
fn w3c_none_es256_refuses_a_changed_signature_and_a_foreign_challenge() {
    use none_es256::*;
    let credential = register(
        UserVerification::NotRequired,
        REG_CHALLENGE,
        REG_CLIENT_DATA,
        ATTESTATION_OBJECT,
    )
    .expect("registers");
    let mut signature = hex(SIGNATURE);
    let last = signature.len() - 1;
    signature[last] ^= 1;
    let verify = |challenge: &[u8], signature: &[u8]| {
        verify_assertion(
            RP,
            UserVerification::NotRequired,
            challenge,
            &credential,
            &hex(CREDENTIAL_ID),
            &hex(AUTH_CLIENT_DATA),
            &hex(AUTH_DATA),
            signature,
        )
    };
    assert_eq!(verify(&hex(AUTH_CHALLENGE), &signature), Err(Refusal::SignatureInvalid));
    assert_eq!(verify(&hex(REG_CHALLENGE), &hex(SIGNATURE)), Err(Refusal::ChallengeMismatch));
    // And registered for another name, the same bytes are another party's.
    let elsewhere = RelyingParty {
        id: "example.com",
        origin: "https://example.org",
    };
    assert_eq!(
        verify_registration(
            elsewhere,
            UserVerification::NotRequired,
            &hex(REG_CHALLENGE),
            &hex(REG_CLIENT_DATA),
            &hex(ATTESTATION_OBJECT),
        ),
        Err(Refusal::RpIdHashMismatch)
    );
}

/// A 1023-byte credential ID — the most WebAuthn allows — and an assertion
/// whose flags carry UV, so it passes the proxy's own setting.
#[test]
fn w3c_long_credential_id_registers_and_its_uv_assertion_verifies_as_required() {
    use long_id_es256::*;
    let credential = register(
        UserVerification::NotRequired,
        REG_CHALLENGE,
        REG_CLIENT_DATA,
        ATTESTATION_OBJECT,
    )
    .expect("registers");
    assert_eq!(credential.id.len(), 1023);
    let id = credential.id.clone();
    verify_assertion(
        RP,
        UserVerification::Required,
        &hex(AUTH_CHALLENGE),
        &credential,
        &id,
        &hex(AUTH_CLIENT_DATA),
        &hex(AUTH_DATA),
        &hex(SIGNATURE),
    )
    .expect("a UV assertion verifies under the proxy's setting");
}

#[test]
fn w3c_cross_origin_registration_is_refused_for_that_alone() {
    use cross_origin_es256::*;
    assert_eq!(
        register(UserVerification::Required, REG_CHALLENGE, REG_CLIENT_DATA, ATTESTATION_OBJECT),
        Err(Refusal::CrossOrigin)
    );
}

/// Packed attestation is refused by format — and the Ed25519 key inside it is
/// read from the same bytes, so the specification's Ed25519 assertion is
/// verified against the specification's Ed25519 key.
#[test]
fn w3c_packed_ed25519_is_refused_by_format_and_its_key_verifies_its_assertion() {
    use packed_ed25519::*;
    assert_eq!(
        register(UserVerification::NotRequired, REG_CHALLENGE, REG_CLIENT_DATA, ATTESTATION_OBJECT),
        Err(Refusal::AttestationFormat("packed".into()))
    );
    // The authData really is the one inside the object.
    let object = hex(ATTESTATION_OBJECT);
    let inner = hex(AUTH_DATA_IN_OBJECT);
    assert!(object.windows(inner.len()).any(|w| w == inner.as_slice()));

    let data = parse_authenticator_data(&inner).expect("readable");
    let attested = data.attested.expect("a credential");
    assert_eq!(attested.algorithm, Algorithm::Ed25519);
    let credential = Credential {
        id: attested.id.clone(),
        algorithm: attested.algorithm,
        public_key: attested.public_key,
        sign_count: data.sign_count,
    };
    verify_assertion(
        RP,
        UserVerification::NotRequired,
        &hex(AUTH_CHALLENGE),
        &credential,
        &attested.id,
        &hex(AUTH_CLIENT_DATA),
        &hex(AUTH_DATA),
        &hex(SIGNATURE),
    )
    .expect("the specification's Ed25519 assertion verifies");
}
